#' Multiple Outcomes
#'
#' 
#' @param data .
#' @param outcomes .
#' @param treat .
#' @param control .
#' @param armTreat .
#' @param covs .
#' @param block .
#' @param bonf .
#' @param sidak .
#' @param holm .
#' @param hochberg .
#' @param bh .
#' @param by .
#' @param wymin .
#' @param wymax .
#' @param rw .
#' @param nperm .
#' @param nboot .
#' @param seed .
#' @param alpha .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$res} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$res$asDF}
#'
#' \code{as.data.frame(results$res)}
#'
#' @export
exmht <- function(
    data,
    outcomes,
    treat,
    control = "",
    armTreat = "",
    covs,
    block,
    bonf = TRUE,
    sidak = FALSE,
    holm = TRUE,
    hochberg = FALSE,
    bh = TRUE,
    by = FALSE,
    wymin = TRUE,
    wymax = FALSE,
    rw = TRUE,
    nperm = 2000,
    nboot = 1000,
    seed = 1234,
    alpha = 0.05,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("exmht requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcomes)) outcomes <- jmvcore::resolveQuo(jmvcore::enquo(outcomes))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(block)) block <- jmvcore::resolveQuo(jmvcore::enquo(block))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcomes), outcomes, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(block), block, NULL))


    options <- exmhtOptions$new(
        outcomes = outcomes,
        treat = treat,
        control = control,
        armTreat = armTreat,
        covs = covs,
        block = block,
        bonf = bonf,
        sidak = sidak,
        holm = holm,
        hochberg = hochberg,
        bh = bh,
        by = by,
        wymin = wymin,
        wymax = wymax,
        rw = rw,
        nperm = nperm,
        nboot = nboot,
        seed = seed,
        alpha = alpha,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- exmhtClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

